SELECT ti.material_code materialCode, ti.material_name materialName, ti.batch, SUM ( ti.inventory_count ) inventoryCount FROM t_inventory ti LEFT JOIN t_location_map tl ON tl.pallet_code = ti.pallet_code
and ti.material_code = #{materialCode}
and ti.batch = #{batch}
and ti.material_name = #{materialName}
and tl.warehouse = #{warehouseName}
GROUP BY ti.material_code, ti.material_name, ti.batch
